package cn.mop.api;
import cn.mop.domain.*;
import cn.mop.domain.manualincident.*;
import java.time.Instant;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class ManualRecoveryConfirmationTest {
    static final Instant NOW=Instant.parse("2026-10-03T05:00:00Z");
    @Test void humanAssertionDoesNotInventMonitoringDispositionTicketOrSla(){var value=new ManualRecoveryConfirmation("  合成人工现场确认😀\n原文\t ",null);assertEquals("HUMAN_CONFIRMED",value.manualRecoveryStatus());assertEquals("SELF_REPORTED",value.verificationStatus());assertEquals("MANUAL_RECOVERY_CONFIRMATION",value.recordSource());assertNull(value.monitorState());assertNull(value.dispositionState());assertFalse(value.monitoringRecoveryApplicable());assertFalse(value.ticketStateChanged());assertFalse(value.slaChanged());}
    @Test void unknownRecoveryTimeStaysUnknownAfterTechnicalRecording(){var value=new ManualRecoveryConfirmation("已人工确认，具体发生时间未提供",null);value.validateRecordedAt(NOW);assertNull(value.reportedRecoveredAt());assertDoesNotThrow(()->new ManualRecoveryConfirmation("历史恢复早于登记也可以明确提供",NOW.minusSeconds(86400)).validateRecordedAt(NOW));}
    @Test void rawTextAndHashPreserveNormalizationAndLineEndings(){var raw=new ManualRecoveryConfirmation("  人工确认\r\n原文😀\t ",null);assertEquals("  人工确认\r\n原文😀\t ",raw.note());assertEquals(64,raw.noteSha256().length());assertNotEquals(raw.noteSha256(),new ManualRecoveryConfirmation(raw.note().replace("\r\n","\n"),null).noteSha256());assertNotEquals(new ManualRecoveryConfirmation("é",null).noteSha256(),new ManualRecoveryConfirmation("e\u0301",null).noteSha256());}
    @Test void explicitNoteRequiredWithCodePointAndControlBounds(){assertEquals(2000,new ManualRecoveryConfirmation("😀".repeat(2000),null).note().codePointCount(0,4000));for(String text:new String[]{null,""," \ufeff\u00a0","x\u0000","x\u0085","x\ud800","😀".repeat(2001)})assertThrows(DomainException.class,()->new ManualRecoveryConfirmation(text,null));}
    @Test void preciseBoundedTimestampCannotBeInFutureOrInventedFromAuditTime(){for(Instant time:new Instant[]{Instant.parse("0000-12-31T23:59:59Z"),Instant.parse("+10000-01-01T00:00:00Z"),NOW.plusNanos(1)})assertThrows(DomainException.class,()->new ManualRecoveryConfirmation("time",time));assertThrows(DomainException.class,()->new ManualRecoveryConfirmation("future",NOW.plusMillis(1)).validateRecordedAt(NOW));assertDoesNotThrow(()->new ManualRecoveryConfirmation("equal",NOW).validateRecordedAt(NOW));assertThrows(DomainException.class,()->new ManualRecoveryConfirmation("note",null).validateRecordedAt(null));assertThrows(DomainException.class,()->new ManualRecoveryConfirmation("note",null).validateRecordedAt(NOW.plusNanos(1)));}
    @Test void firstExplicitConfirmationUsesZeroToOneAndCannotOverwriteExistingEvidence(){assertDoesNotThrow(()->ManualRecoveryConfirmation.requireConfirmable(0,0));assertEquals(409,assertThrows(DomainException.class,()->ManualRecoveryConfirmation.requireConfirmable(0,1)).status);assertEquals(422,assertThrows(DomainException.class,()->ManualRecoveryConfirmation.requireConfirmable(1,1)).status);assertEquals(400,assertThrows(DomainException.class,()->ManualRecoveryConfirmation.requireConfirmable(-1,0)).status);assertEquals(503,assertThrows(DomainException.class,()->ManualRecoveryConfirmation.requireConfirmable(0,2)).status);}
    @Test void confirmationProjectionCannotConfuseAbsenceWithConfirmedOrAnotherParent(){var empty=new ManualRecoveryRepository.Current("incident","tenant",0,null);assertEquals("NOT_CONFIRMED",empty.manualRecoveryStatus());var confirmation=new ManualRecoveryRepository.Confirmation("id","tenant","incident","actor",new ManualRecoveryConfirmation("explicit",null),NOW);assertEquals("HUMAN_CONFIRMED",new ManualRecoveryRepository.Current("incident","tenant",1,confirmation).manualRecoveryStatus());assertThrows(IllegalArgumentException.class,()->new ManualRecoveryRepository.Current("incident","tenant",1,null));assertThrows(IllegalArgumentException.class,()->new ManualRecoveryRepository.Current("incident","tenant",0,confirmation));assertThrows(IllegalArgumentException.class,()->new ManualRecoveryRepository.Current("other","tenant",1,confirmation));}
    @Test void originalRegistrationRemainsUnconfirmedSnapshotSeparateFromNewHumanEvidence(){var incident=new ManualIncident("合成原始登记",ManualIncident.Severity.HIGH,"55000000-0000-4000-8000-000000000001",1);var recovery=new ManualRecoveryConfirmation("人工核验后单独记录",null);assertEquals("NOT_CONFIRMED",incident.manualRecoveryStatus());assertNull(incident.recoveredAt());assertEquals("HUMAN_CONFIRMED",recovery.manualRecoveryStatus());assertNull(recovery.reportedRecoveredAt());}
    @Test void storedConfirmationRequiresNamedHumanParentAndValidServerTimestamp(){var value=new ManualRecoveryConfirmation("explicit",NOW);assertThrows(IllegalArgumentException.class,()->new ManualRecoveryRepository.Confirmation("id","tenant","incident","",value,NOW));assertThrows(IllegalArgumentException.class,()->new ManualRecoveryRepository.Confirmation("id","tenant","incident","actor",null,NOW));assertThrows(DomainException.class,()->new ManualRecoveryRepository.Confirmation("id","tenant","incident","actor",value,NOW.minusMillis(1)));assertThrows(IllegalArgumentException.class,()->new ManualRecoveryRepository.Current(null,"tenant",0,null));}

}
